(window.HistoryAtlas.PERSONS = window.HistoryAtlas.PERSONS || {})["dante-alighieri"] = {"id":"dante-alighieri","name":"但丁·阿利吉耶里","name_alt":"意大利语 Dante Alighieri","group":"世界","born":1265,"died":1321,"born_approx":false,"died_approx":false,"role":"意大利诗人、政治家","polity":"","summary":"佛罗伦萨人，青年时参加坎帕尔迪诺战役，写成《新生》。投身城邦政治，1300年任执政官之一；属归尔甫派中的白党，1302年黑党掌权后被缺席判处流放，此后终身未能返乡，先后寄居维罗纳、卢尼贾纳、拉文纳等地。流亡期间写成《飨宴》《论俗语》《帝制论》与《神曲》。1321年出使威尼斯归来后病逝于拉文纳。流亡初期的行踪多为学界推测。","confidence":"史料确证","sources":"但丁《新生》《神曲》《书信集》；迪诺·孔帕尼《编年史》；乔瓦尼·维拉尼《新编年史》；薄伽丘《但丁传》；佛罗伦萨判决书档案；Marco Santagata《但丁：其人其诗》","stops":[{"year":1265,"to":1265,"x":749,"y":181.3,"place":"佛罗伦萨（今意大利佛罗伦萨）","event":"约五六月间生于佛罗伦萨一个没落小贵族家庭。","kind":"出生","confidence":"史料确证","source":"《神曲·天堂篇》第二十二歌；薄伽丘《但丁传》"},{"year":1274,"to":1274,"x":749,"y":181.3,"place":"佛罗伦萨（今意大利佛罗伦萨）","event":"据《新生》自述，九岁时初见贝雅特丽齐（一般认为即贝雅特丽齐·波尔蒂纳里）。","kind":"其他","confidence":"学界推测","source":"《新生》第二章；薄伽丘《但丁传》"},{"year":1289,"to":1289,"x":750.6,"y":181.3,"place":"坎帕尔迪诺（今意大利托斯卡纳大区波皮附近）","event":"六月作为骑兵参加佛罗伦萨归尔甫派对阿雷佐吉伯林派的坎帕尔迪诺战役；同年参与卡普罗纳城堡之围。","kind":"征战","confidence":"史料确证","source":"莱奥纳尔多·布鲁尼《但丁传》（引但丁书信）；《神曲·地狱篇》第二十一至二十二歌"},{"year":1290,"to":1294,"x":749,"y":181.3,"place":"佛罗伦萨（今意大利佛罗伦萨）","event":"1290年贝雅特丽齐去世；其后以散文与诗歌结合写成《新生》，并研读哲学。","kind":"著述","confidence":"学界推测","source":"《新生》；《飨宴》卷二"},{"year":1295,"to":1295,"x":749,"y":181.3,"place":"佛罗伦萨（今意大利佛罗伦萨）","event":"加入医生与药剂师行会，从而取得担任公职的资格，进入城邦议事机构。","kind":"任职","confidence":"史料确证","source":"佛罗伦萨议事会记录；Santagata《但丁》"},{"year":1300,"to":1300,"x":749,"y":181.3,"place":"佛罗伦萨（今意大利佛罗伦萨）","event":"六月十五日至八月十五日任佛罗伦萨六名执政官之一，期间流放黑白两党首领，其中包括其友圭多·卡瓦尔坎蒂。","kind":"任职","confidence":"史料确证","source":"迪诺·孔帕尼《编年史》卷一；乔瓦尼·维拉尼《新编年史》"},{"year":1301,"to":1301,"x":753.8,"y":190.8,"place":"罗马（今意大利罗马）","event":"据孔帕尼记载，秋季作为白党政府使节赴罗马觐见教宗博尼法斯八世；期间瓦卢瓦的查理进入佛罗伦萨，黑党掌权。","kind":"出使","confidence":"学界推测","source":"迪诺·孔帕尼《编年史》卷二"},{"year":1302,"to":1302,"x":750.2,"y":180.8,"place":"圣戈登佐修道院（今意大利佛罗伦萨省圣戈登佐）","event":"一月被缺席判处贪污等罪名并流放，三月改判若返城即处火刑；六月出席白党流亡者与吉伯林派在圣戈登佐修道院的结盟会议。","kind":"流亡","confidence":"史料确证","source":"佛罗伦萨1302年判决书（《银书》）；圣戈登佐盟约文书"},{"year":1303,"to":1304,"x":747.8,"y":173.4,"place":"维罗纳（今意大利维罗纳）","event":"与白党流亡者决裂，首次投奔维罗纳领主巴尔托洛梅奥·德拉·斯卡拉，称其为“第一个避难所”。","kind":"流亡","confidence":"学界推测","source":"《神曲·天堂篇》第十七歌"},{"year":1304,"to":1306,"x":749,"y":177.9,"place":"博洛尼亚（今意大利博洛尼亚）","event":"可能寄居博洛尼亚等地，撰写《飨宴》与《论俗语》（均未完成）。","kind":"著述","confidence":"学界推测","source":"Santagata《但丁》；博洛尼亚公证文书中抄录的但丁诗作"},{"year":1306,"to":1306,"x":743.9,"y":179.8,"place":"卡斯泰尔诺沃马格拉（今意大利拉斯佩齐亚省）","event":"十月六日作为卢尼贾纳的马拉斯皮纳家族代理人，与卢尼主教签订和约，文书原件存世。","kind":"其他","confidence":"史料确证","source":"卡斯泰尔诺沃和约公证文书（1306年10月6日）"},{"year":1307,"to":1309,"x":743.9,"y":179.3,"place":"卢尼贾纳（今意大利托斯卡纳大区西北部）","event":"寄居马拉斯皮纳家族领地及卡森蒂诺等地，约此时开始创作《神曲·地狱篇》。","kind":"著述","confidence":"学界推测","source":"《神曲·炼狱篇》第八歌；Santagata《但丁》"},{"year":1311,"to":1311,"x":751,"y":181.8,"place":"卡森蒂诺（今意大利托斯卡纳大区波皮一带）","event":"支持南下意大利的皇帝亨利七世，写信斥责佛罗伦萨人并劝亨利七世进攻佛罗伦萨，信末署“写于阿诺河源头附近”；约此时写《帝制论》（年份有争议）。","kind":"著述","confidence":"史料确证","source":"但丁《书信集》第六、七封"},{"year":1312,"to":1318,"x":747.8,"y":173.4,"place":"维罗纳（今意大利维罗纳）","event":"亨利七世死后寄居维罗纳领主坎格兰德·德拉·斯卡拉宫廷，续写《神曲》；1315年拒绝以认罪为条件的大赦，判决随之重申。","kind":"著述","confidence":"学界推测","source":"但丁《书信集》第十二、十三封；佛罗伦萨1315年判决书"},{"year":1319,"to":1320,"x":752.5,"y":178.4,"place":"拉文纳（今意大利拉文纳）","event":"应拉文纳领主圭多·诺韦洛·达·波伦塔之邀移居拉文纳，完成《神曲·天堂篇》；1320年一月曾在维罗纳讲演《水与土问题》。","kind":"著述","confidence":"学界推测","source":"薄伽丘《但丁传》；《水与土问题》"},{"year":1321,"to":1321,"x":752.9,"y":173.4,"place":"威尼斯（今意大利威尼斯）","event":"夏季代表拉文纳出使威尼斯，归途中染病（一般认为是疟疾）。","kind":"出使","confidence":"学界推测","source":"乔瓦尼·维拉尼《新编年史》卷十；薄伽丘《但丁传》"},{"year":1321,"to":1321,"x":752.5,"y":178.4,"place":"拉文纳（今意大利拉文纳）","event":"九月十三日至十四日夜间卒于拉文纳，葬于圣方济各教堂。","kind":"去世","confidence":"史料确证","source":"乔瓦尼·维拉尼《新编年史》卷十；薄伽丘《但丁传》"}]};
